import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Write post starts the assigned task","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-write-start/spec.md","filePath":"feature/content-task-workflow/task-write-start/spec.md"}'),r={name:"feature/content-task-workflow/task-write-start/spec.md"};function o(n,e,c,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="write-post-starts-the-assigned-task" tabindex="-1">Write post starts the assigned task <a class="header-anchor" href="#write-post-starts-the-assigned-task" aria-label="Permalink to &quot;Write post starts the assigned task&quot;">​</a></h1><h2 id="objective-user-story" tabindex="-1">Objective / user story <a class="header-anchor" href="#objective-user-story" aria-label="Permalink to &quot;Objective / user story&quot;">​</a></h2><p>Creator selects “Viết bài” once to start an assigned TODO POST task and enter Editor, without a separate start confirmation or a second navigation click. User confirmed this interaction on 2026-10-21.</p><h2 id="acceptance-criteria-ui-states" tabindex="-1">Acceptance criteria / UI states <a class="header-anchor" href="#acceptance-criteria-ui-states" aria-label="Permalink to &quot;Acceptance criteria / UI states&quot;">​</a></h2><ul><li>Assigned Creator + TODO: the explicit Write post click calls the existing Start API. Navigate to the linked Editor only after successful IN_PROGRESS response.</li><li>Assigned Creator + IN_PROGRESS: open Editor directly; do not start again.</li><li>Non-assignees/unassigned tasks do not gain write/start permission. Keep readonly navigation neutrally labeled. Review/final/cancelled states never restart.</li><li>Both list and Task Detail use the same start action implementation.</li><li>Pending: spinner and disabled button; synchronous duplicate-click guard.</li><li>Failure: accessible inline error, remain on the current page, allow retry.</li><li>Opening a URL alone does not start work. Preserve revision checking, required brief/deadline, campaign restrictions, and backend authorization.</li><li>i18n: add parallel <code>tasks.workflow.writePost</code> in vi/en, update existing startHint to explain that Write post also explicitly starts a POST task; reuse existing <code>tasks.review.openEditor</code>, workflow errors/success.</li><li>Light/dark: reuse Button and TaskWorkflowError semantic tokens; no new palette.</li></ul><h2 id="api-errors-edge-cases" tabindex="-1">API / errors / edge cases <a class="header-anchor" href="#api-errors-edge-cases" aria-label="Permalink to &quot;API / errors / edge cases&quot;">​</a></h2><p>Existing POST <code>/api/v1/workspaces/{workspaceId}/tasks/{taskId}/start</code> with <code>expectedRevision</code>; existing workflow query supplies the revision. A failed request must not navigate or locally fake IN_PROGRESS. Keep other task types&#39; Start work behavior. Double clicks must not duplicate the command.</p><h2 id="definition-of-done-out-of-scope" tabindex="-1">Definition of done / out of scope <a class="header-anchor" href="#definition-of-done-out-of-scope" aria-label="Permalink to &quot;Definition of done / out of scope&quot;">​</a></h2><p>Check API-before-navigation ordering, failure/retry, direct open, permissions, keyboard, locales/themes, typecheck/lint. No migration, assignment change, automatic start on page load, billing/AI call, publish or approval changes.</p>',9)])])}const k=t(r,[["render",o]]);export{h as __pageData,k as default};
